n = 0
for slug, (feats, exps) in S.items():
    f = f'services-mills-{slug}.html'; h = open(f).read(); o = h
    it = iter(feats)
    def rf(m):
        t = next(it); return m.group(0) if t is None else m.group(1) + html.escape(t, quote=False) + m.group(3)
    h = re.sub(r'(<p class="service-feature__text">)(.*?)(</p>)', rf, h, flags=re.S)
    a = h.find('What you can expect from The Mills'); e = h.find('</section>', a)
    blk = h[a:e]; it2 = iter(exps)
    blk = re.sub(r'(<p class="info-card__text">)(.*?)(</p>)', lambda m: m.group(1) + html.escape(next(it2), quote=False) + m.group(3), blk, flags=re.S)
    h = h[:a] + blk + h[e:]
    if h != o: open(f, 'w').write(h); n += 1
print('service pages rewritten:', n)
